import{_ as t,o as a,c as o,a5 as i}from"./chunks/framework.B-qY3dMa.js";const h=JSON.parse('{"title":"为什么 API 调用报 401 Unauthorized？","description":"","frontmatter":{"title":"为什么 API 调用报 401 Unauthorized？","date":"2026-05-18T00:00:00.000Z","category":"常见问题","tags":["报错",401,"API Key"]},"headers":[],"relativePath":"faq/401-unauthorized.md","filePath":"faq/401-unauthorized.md","lastUpdated":1779089963000}'),r={name:"faq/401-unauthorized.md"};function l(n,e,s,d,c,u){return a(),o("div",null,[...e[0]||(e[0]=[i('<h2 id="错误原因" tabindex="-1">错误原因 <a class="header-anchor" href="#错误原因" aria-label="Permalink to &quot;错误原因&quot;">​</a></h2><p>出现 401 通常是 API Key 的问题，排查以下几点：</p><ul><li><strong>Key 填写错误</strong>：复制时多了空格、少了字符，或中间断行</li><li><strong>Key 已失效</strong>：被手动删除、禁用，或账户异常导致 Key 无效</li><li><strong>Key 未激活</strong>：新创建的 Key 偶尔需要等几秒才生效</li></ul><h2 id="解决方法" tabindex="-1">解决方法 <a class="header-anchor" href="#解决方法" aria-label="Permalink to &quot;解决方法&quot;">​</a></h2><ol><li>回到熊猫算力平台，重新复制 API Key（点击复制按钮，不要手动选择）</li><li>粘贴后检查 Key 首尾有无多余空格</li><li>确认 Key 状态显示&quot;正常&quot;，未被禁用</li><li>重新发起请求</li></ol><div class="warning custom-block"><p class="custom-block-title">注意</p><p>API Key 一旦泄露请立即删除并重新生成，不要在公开代码或截图中暴露你的 Key。</p></div>',6)])])}const p=t(r,[["render",l]]);export{h as __pageData,p as default};
